SELECT jsonb_build_object(
 'captured_at_utc',clock_timestamp(),
 'database',current_database(),
 'db_user',current_user,
 'postgres_version',version(),
 'alembic_versions',(SELECT jsonb_agg(version_num) FROM alembic_version),
 'counts',jsonb_build_object(
   'master_total',(SELECT count(*) FROM opportunities),
   'non_merged',(SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL),
   'merged',(SELECT count(*) FROM opportunities WHERE merged_into_id IS NOT NULL),
   'source_opportunities',(SELECT count(*) FROM source_opportunities),
   'source_observations',(SELECT count(*) FROM source_observations),
   'alahsa_nonmerged',(SELECT count(*) FROM opportunities o JOIN geographic_reference_units g ON g.id=o.geography_reference_unit_id WHERE o.merged_into_id IS NULL AND g.level='governorate' AND g.external_id='501'),
   'all_public_tables',(SELECT jsonb_agg(tablename ORDER BY tablename) FROM pg_tables WHERE schemaname='public')),
 'scope_distribution_nonmerged',(SELECT jsonb_object_agg(coalesce(geographic_scope,'NULL'),n) FROM (SELECT geographic_scope,count(*) n FROM opportunities WHERE merged_into_id IS NULL GROUP BY geographic_scope) s),
 'governorate_distribution_nonmerged',(SELECT jsonb_agg(jsonb_build_object('governorate',g.external_id,'region',pg.external_id,'count',n) ORDER BY pg.external_id,g.external_id) FROM (SELECT geography_reference_unit_id,count(*) n FROM opportunities WHERE merged_into_id IS NULL GROUP BY geography_reference_unit_id) x JOIN geographic_reference_units g ON g.id=x.geography_reference_unit_id LEFT JOIN geographic_reference_units pg ON pg.id=g.parent_id),
 'sources',(SELECT jsonb_agg(jsonb_build_object('source_key',source_key,'enabled',enabled,'polling_frequency_minutes',polling_frequency_minutes,'sync_status',sync_status,'last_attempted_sync',last_attempted_sync,'last_successful_sync',last_successful_sync) ORDER BY source_key) FROM sources WHERE source_key IN ('furas','rcu-investment-opportunities')),
 'target_count',(SELECT count(*) FROM approved),
 'target_rows',(SELECT jsonb_agg(jsonb_build_object(
   'approved_master_id',a.master_id,'expected_canonical_id',a.canonical_id,'expected_provider_id',a.provider_id,'expected_source_row_id',a.source_row_id,'expected_latitude',a.latitude,'expected_longitude',a.longitude,'expected_source_url',a.source_url,
   'provider_global_collision_count',(SELECT count(*) FROM source_opportunities sx JOIN sources ss ON ss.id=sx.source_id WHERE ss.source_key='furas' AND sx.source_opportunity_id=a.provider_id),
   'master',to_jsonb(o),'governorate_external_id',g.external_id,'parent_region_external_id',pg.external_id,
   'furas_links',(SELECT jsonb_agg(to_jsonb(so)||jsonb_build_object('source_key',s.source_key,'observation_count',(SELECT count(*) FROM source_observations ob WHERE ob.source_opportunity_id=so.id)) ORDER BY so.id) FROM source_opportunities so JOIN sources s ON s.id=so.source_id WHERE so.master_opportunity_id=o.id AND s.source_key='furas'),
   'all_source_links',(SELECT count(*) FROM source_opportunities so WHERE so.master_opportunity_id=o.id),
   'open_conflicts',(SELECT count(*) FROM opportunity_data_conflicts c WHERE c.opportunity_id=o.id AND c.status IN ('OPEN','PENDING')),
   'open_reviews',(SELECT count(*) FROM location_reviews lr WHERE lr.source_record_id=a.source_row_id AND lr.status IN ('OPEN','PENDING'))
 ) ORDER BY a.master_id) FROM approved a LEFT JOIN opportunities o ON o.id=a.master_id LEFT JOIN geographic_reference_units g ON g.id=o.geography_reference_unit_id LEFT JOIN geographic_reference_units pg ON pg.id=g.parent_id),
 'opportunity_update_triggers',(SELECT jsonb_agg(jsonb_build_object('name',tgname,'definition',pg_get_triggerdef(oid)) ORDER BY tgname) FROM pg_trigger WHERE tgrelid='opportunities'::regclass AND NOT tgisinternal),
 'tables_with_job_or_alias',(SELECT jsonb_agg(tablename ORDER BY tablename) FROM pg_tables WHERE schemaname='public' AND (tablename ILIKE '%job%' OR tablename ILIKE '%alias%'))
)::text;
COMMIT;